const request = { schema: 1, job: jobBinding, rootGoSha256: admission.rootHash, recipeSha256: admission.recipeHash, evidenceRoot, scratchRoot, materializationRoot, workerRole: dispatch, bindings: { ...bindings }, deadline: { globalNs: globalDeadline.toString(), phaseNs: requestClock.phaseDeadlineNs, jobNs: requestClock.jobDeadlineNs, workNs: workDeadline.toString(), reservationNs: requestClock.reservationNs }, nonce: randomUUID(), activeRoots: admission.recipe.activeRoots, data: admission.recipe.data, workerModule, controlEnrollments: admission.root.controlEnrollments };
const artifact = atomicJson(join(evidenceRoot, 'request.json'), request);
const context = { name, job: jobBinding, request, home, temporary, tools: 0, compilers: 0, git: 0, rawBudget: { remaining: 33554432 - artifact.bytes - 4194304 }, rawReceipts: [], generated: [], toolFailure: false, toolPromise: null, phase: new PhaseCapture(join(evidenceRoot, 'phases.ndjson'), job, request.deadline), received: 0, sent: 0, result: null, unsafe: false, inflight: false, registrations: [] };
currentContext = context;
context.phase.record('outer-admission', { reservationNs: requestClock.reservationNs, preflightStartedNs, preflightEndedNs, workerModule, deadline: request.deadline });
const owner = startOwned({ role: 'outer', executable: join(admission.root.toolchain.root, admission.root.toolchain.node), argv: [join(coreDirectory, 'worker-host.mjs'), artifact.path, artifact.sha256], cwd: scratchRoot, env: cleanEnvironment(home, temporary), directory: evidenceRoot, name: 'worker', ipc: true, captureLimit: 16777216, budget: context.rawBudget, workDeadline, hardDeadline: BigInt(requestClock.jobDeadlineNs), currentDeadline: () => context.phase.currentDeadline() });

} else if (message.type === 'RESULT') {
  requireFact(context.result === null && context.phase.index === 5, 'DUPLICATE_OR_EARLY_RESULT');
  keys(message.payload, ['schema', 'jobId', 'environment', 'role', 'status', 'details', 'artifacts', 'stageOutput', 'rootGoSha256', 'recipeSha256']);
  requireFact(message.payload.schema === 1 && message.payload.jobId === job.id && message.payload.environment === (jobBinding.environment ?? null) && message.payload.rootGoSha256 === admission.rootHash && message.payload.recipeSha256 === admission.recipeHash && ['PASS', 'FAIL', 'INCOMPLETE', 'UNRUN'].includes(message.payload.status), 'RECEIPT_BINDING');
  context.result = message.payload;
  atomicJson(join(evidenceRoot, 'job-receipt.json'), message.payload);
  value = { recorded: true };

context.rawReceipts.push(processReceipt);
let integrity = false;
try {
  guard();
  for (const raw of context.rawReceipts) for (const stream of ['stdout', 'stderr']) { const current = fileDigest(raw[`${stream}Path`]); requireFact(current.sha256 === raw[`${stream}Sha256`] && current.bytes === raw[`${stream}Bytes`] && current.mode === 384, 'RAW_CAPTURE_CHANGED'); }
  integrity = true;
} catch (error) { context.unsafe = true; atomicJson(join(evidenceRoot, 'integrity-failure.json'), describeError(error)); }

atomicJson(join(evidenceRoot, 'outer-outcome.json'), result);
const manifest = snapshot(evidenceRoot, evidenceLimits);
const workManifest = snapshot(workRoot, evidenceLimits);
closedWorks.push({ name, root: workRoot, manifest: workManifest, identity: identity(workRoot) });
counters.disk += Object.values(manifest.files).concat(Object.values(workManifest.files)).reduce((sum, descriptor) => sum + descriptor.bytes, 0);
requireFact(counters.disk <= 25769803776, 'COHORT_DISK');
closedJobs.push({ name, root: evidenceRoot, manifest });

const finish = reaped => {
  if (settled) return;
  settled = true;
  clearInterval(timer);
  for (const stream of Object.values(output)) { fsyncSync(stream.descriptor); closeSync(stream.descriptor); }
  const receipt = { role: options.role, pid: child.pid ?? null, group: child.pid ?? null, registeredBeforeSpawnNs: reservation.registeredBeforeSpawnNs, code: exitCode, signal: exitSignal, timedOut, overflow, spawnError, closeObserved, reaped, termSentNs: termAt?.toString() ?? null, killSentNs: killAt?.toString() ?? null, closedNs: closedAt?.toString() ?? null, workDeadlineNs: options.workDeadline.toString(), hardDeadlineNs: options.hardDeadline.toString(), endedNs: now().toString() };
  for (const [name, stream] of Object.entries(output)) { receipt[`${name}Path`] = stream.path; receipt[`${name}Bytes`] = stream.bytes; receipt[`${name}Sha256`] = stream.digest.digest('hex'); }
  atomicJson(join(options.directory, `${options.name}.process.json`), receipt);
  if (reaped) active.delete(reservation);
  resolveDone(receipt);

const writeBytes = async (relativePath, bytes) => {
  safeRelative(relativePath);
  requireFact(bytes instanceof Uint8Array && (writtenBytes += bytes.length) <= 33554432, 'WORKER_METADATA_TOTAL');
  await rpc('EVIDENCE_RESERVE', { bytes: bytes.length });
  let parent = request.evidenceRoot;
  for (const part of relative(request.evidenceRoot, dirname(join(request.evidenceRoot, relativePath))).split('/').filter(Boolean)) { parent = join(parent, part); if (!existsSync(parent)) newDirectory(parent); }
  const artifact = atomicBytes(join(request.evidenceRoot, relativePath), bytes);
  await note('artifact', artifact);
  return artifact;
};
const writeJson = (relativePath, value) => writeBytes(relativePath, Buffer.from(`${JSON.stringify(value)}\n`));
